import AppKit

public enum AppAssets {
    private static let base64Png = ""

    public static func originalIcon() -> NSImage? {
        // 1. Check bundle resources
        if let url = Bundle.main.url(forResource: "quotty", withExtension: "png"),
           let img = NSImage(contentsOf: url) {
            return img
        }
        if let url = Bundle.main.url(forResource: "AppIcon", withExtension: "icns"),
           let img = NSImage(contentsOf: url) {
            return img
        }
        if let named = NSImage(named: "AppIcon") {
            return named
        }

        // 2. Check relative file paths for dev/debug
        for p in ["assets/quotty.png", "../assets/quotty.png"] {
            if let img = NSImage(contentsOfFile: p) {
                return img
            }
        }

        // 3. Fallback to embedded original 256x256 icon
        if let data = Data(base64Encoded: base64Png, options: .ignoreUnknownCharacters) {
            return NSImage(data: data)
        }

        return nil
    }

    public static func appIcon() -> NSImage? {
        guard let img = originalIcon() else { return nil }
        return (img.copy() as? NSImage) ?? img
    }

    public static func menuBarIcon() -> NSImage? {
        guard let img = originalIcon() else { return nil }
        let icon = (img.copy() as? NSImage) ?? img
        icon.size = NSSize(width: 18, height: 18)
        icon.isTemplate = false
        return icon
    }
}
